let store={version:2,current:null,records:[],bookmarks:[],read:[],answers:{},posts:[],replies:{},liked:[],draft:{title:'',body:'',tag:'家乡记忆'},sound:false},storageOK=true,busy=false,filter='全部',quizIndex=0;
try{const data=JSON.parse(localStorage.getItem(KEY));if(data?.version===2){for(const key of ['records','bookmarks','read','posts','liked'])if(Array.isArray(data[key]))store[key]=data[key];for(const key of ['answers','replies','draft'])if(data[key]&&typeof data[key]==='object'&&!Array.isArray(data[key]))store[key]=data[key];if(data.current&&Culture.validLines(data.current.lines))store.current=data.current;store.sound=!!data.sound;if(typeof data.chatDraft==='string')store.chatDraft=data.chatDraft.slice(0,1000);}}catch{storageOK=false;}
