function categoryLabel(tag){return ({'全部':'All','家乡记忆':'Local memories','经典共读':'Shared reading','知识问答':'Questions'})[tag]||tag;}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';window.MotionUI?.toast();clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3000);}
