function landscape(){return `<div class="art culture-art" role="img" aria-label="A color-block coin among blue-green mountains, a river and a pavilion"><svg viewBox="0 0 400 340" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><pattern id="grain" width="8" height="8" patternUnits="userSpaceOnUse"><circle cx="2" cy="3" r=".6" fill="#F4EDDE" opacity=".16"/></pattern></defs><rect width="400" height="340" fill="#EAE0C9"/><circle cx="285" cy="68" r="46" fill="#C89B5A"/><path d="M0 255L70 83l45 88L176 53l70 155L305 120l95 122v98H0" fill="#2C6A7E"/><path d="M0 273l94-113 78 110 59-127 82 115 87-58v140H0" fill="#5A9778"/><path d="M0 307q104-70 190-8t210-14v55H0" fill="#1F4E5F"/><path d="M208 340q72-24 34-47t25-30" stroke="#C89B5A" stroke-width="13" fill="none"/><g transform="translate(145 105) rotate(-12 55 55)"><circle cx="60" cy="67" r="59" fill="#A97C3F"/><circle cx="55" cy="58" r="59" fill="#C89B5A"/><circle cx="55" cy="58" r="49" fill="none" stroke="#F4EDDE" stroke-width="2"/><path d="M39 42h32v32H39z" fill="#1F4E5F"/><path d="M47 20h16m-8-8v16m-37 27h12m51 0h12M47 95h16" stroke="#1F4E5F" stroke-width="4"/></g><path d="M60 275v-34h36v34M48 241q33-12 31-23 5 11 29 23" fill="#1F4E5F"/><path d="M68 249h8v26h-8m12-26h8v26h-8" fill="#C89B5A"/><path d="M15 57q13-17 25-4 12-28 29-7 14-8 22 10" fill="none" stroke="#F4EDDE" stroke-width="9"/><rect width="400" height="340" fill="url(#grain)"/></svg><span class="art-label">Nature, symbols and living heritage</span><span class="chapter-mark">Qianli Coins / Culture in everyday life</span></div>`;}
function home(){return `<div class="hero"><div class="hero-copy"><p class="eyebrow">Heritage · Learning · Conversation</p><h1>Cast a coin.<br>Discover a tradition.</h1><p class="hero-desc">Explore symbols, texts and local memories.<br>Keep culture alive through learning and sharing.</p><button class="primary" data-action="start">${store.current?'Continue casting':'Explore the coins'} ↗</button><p class="micro">Six casts · Discover the symbols · Reflect</p></div>${landscape()}</div><div class="feature-row"><a class="feature" href="#library"><b>01 &nbsp; Explore culture</b><span>Short guides with sources</span></a><a class="feature" href="#quiz"><b>02 &nbsp; Test your knowledge</b><span>Build understanding with a short quiz</span></a><a class="feature" href="#community"><b>03 &nbsp; Share a memory</b><span>Record customs and exchange perspectives</span></a></div><div class="section-head"><h2>A starting point</h2><a href="#library" class="micro">All guides →</a></div><div class="chapter-list">${LESSONS.map((l,i)=>`<a href="#lesson/${l.id}" class="chapter-item"><span>${l.symbol}</span><div><b>${l.title}</b><small>${l.tag}</small></div></a>`).join('')}</div><div class="purpose"><span class="badge">Living cultural heritage</span><p>Learn something, record a memory, then share it. Keep cultural knowledge alive through lifelong learning and conversation across places and generations.</p><a href="#community" class="text-link">Join the conversation →</a></div>`;}
function yao(lines){const names={6:'Changing yin',7:'Stable yang',8:'Stable yin',9:'Changing yang'};return `<div class="yao-board"><div class="yao" role="img" aria-label="${lines.length?lines.map((n,i)=>`Line ${i+1}: ${names[n]}`).join(', '):'No lines have been cast yet'}">${Array.from({length:6},(_,i)=>`<div class="yao-row ${lines[i]?'':'empty'} ${[6,9].includes(lines[i])?'changing':''}"><i></i>${[6,8].includes(lines[i])?'<i></i>':''}</div>`).join('')}</div><p class="micro center">Read from bottom to top. Red marks changing lines.</p></div>`;}
function play(){const s=store.current;if(!s)return `<div class="screen"><h1>One cast.<br>One line to discover.</h1><button class="primary wide" data-action="start">Explore the coins ↗</button></div>`;if(s.lines.length===6)return result(s);return `<div class="screen"><a class="back" href="#home">← Back to Home</a><p class="eyebrow">Cast & Discover · Culture Lab</p><h1>Cast the coins.<br>Build the six lines.</h1><p>Three coins. Six casts. Discover yin and yang lines and learn how a hexagram is formed.</p><div class="coin-stage"><span class="coin"></span><span class="coin"></span><span class="coin"></span></div>${yao(s.lines)}<p class="center" aria-live="polite">${s.lines.length} / 6 casts complete</p><button class="primary wide" data-action="toss" ${busy?'disabled':''}>Cast ${s.lines.length+1} of 6</button><div class="center"><button class="text-button" data-action="quick" ${busy?'disabled':''}>Complete the remaining casts</button></div><details><summary>How does this work?</summary><p>Each virtual coin has an equal chance of scoring 2 or 3. Three coins total 6, 7, 8 or 9; 6 and 9 are changing lines. This random simulation introduces cultural symbols, rather than predicting real-world events.</p></details></div>`;}
function result(s){const r=Culture.decode(s.lines,HEXAGRAMS);return `<div class="screen"><a class="back" href="#home">← Back to Home</a><p class="eyebrow">Six lines complete · Start with the symbols</p><h1>${esc(r.hex.name)}</h1><div class="hex-result"><span class="hex-symbol">${r.hex.symbol}</span><div><p>Upper trigram:${r.upper.symbol} ${r.upper.name} · ${r.upper.nature}</p><p>Lower trigram:${r.lower.symbol} ${r.lower.name} · ${r.lower.nature}</p></div></div>${yao(s.lines)}<div class="lens"><span class="badge">Reading theme · Editorial guide</span><p class="quote">${esc(r.hex.judgment)}</p><p class="micro">Hexagram ${r.hex.id}: ${esc(r.hex.name)}. This brief English learning guide is not a full translation of the ancient text.</p><a href="https://ctext.org/book-of-changes/yi-jing/zhs" target="_blank" rel="noopener" class="text-link">Explore the Book of Changes source text ↗</a></div><h2>Understand the structure</h2><p>The lower trigram is ${r.lower.name} and the upper trigram is ${r.upper.name}. Begin by comparing their natural images: ${r.lower.nature} and ${r.upper.nature}.</p><p>${r.moving.length?`Changing lines: ${r.moving.join(', ')}. Reversing their yin and yang forms gives ${r.changed.name}.`:'There are no changing lines in this cast, so the structure stays the same.'}</p><p class="micro">This explains the symbols, not personal fortune or future outcomes.</p><a class="secondary wide" href="#lesson/symbols">Read: Meet the eight trigrams →</a><details><summary>Explore the six-line structure</summary>${r.hex.lines.map(line=>`<p>${esc(line)}</p>`).join('')}</details>${Journey.checkpoint(s)}<details><summary>Original Chinese text</summary><p>${esc(r.hex.originalJudgment)}</p>${r.hex.originalLines.map(line=>`<p lang="zh-CN">${esc(line)}</p>`).join('')}</details><label for="note">What did you notice? What would you like to explore?</label><textarea id="note" maxlength="1000" placeholder="Write down a discovery or a question…">${esc(s.note)}</textarea><p class="micro">This note stays on your device. It is not posted to Discuss.</p><button class="primary wide" data-action="save-result">Save to Journal ↗</button></div>`;}
function library(){return `<div class="screen"><p class="eyebrow">Library · Build understanding</p><h1>Understand it.<br>Pass it on.</h1><p>Explore sourced readings and clearly marked commentary. Build your own understanding, one idea at a time.</p><a class="primary wide" href="#quiz">Knowledge quiz · Four questions ↗</a><div class="book-grid">${LESSONS.map(l=>`<article class="book-card"><span class="library-symbol">${l.symbol}</span><p class="micro">${l.tag} ${store.read.includes(l.id)?'· Read':''}</p><h2>${l.title}</h2><p>${l.intro}</p><div class="actions"><a class="secondary" href="#lesson/${l.id}">Start reading →</a><button class="bookmark" data-bookmark="${l.id}" aria-pressed="${store.bookmarks.includes(l.id)}">${store.bookmarks.includes(l.id)?'★ Saved':'☆ Save'}</button></div></article>`).join('')}</div><div class="purpose"><p class="micro">Source excerpts and modern commentary are labelled separately. Our advice on recording customs is original editorial guidance.</p></div></div>`;}
function lesson(id){const l=LESSONS.find(x=>x.id===id);if(!l)return missing();return `<article class="screen"><a class="back" href="#library">← Back to Library</a><p class="eyebrow">${l.tag}</p><h1>${l.title}</h1><p class="muted">${l.intro}</p>${id==='symbols'?Journey.resume():''}${l.quote?`<div class="lens"><span class="badge">Source excerpt · English rendering</span><p class="quote">${l.quote}</p><p class="micro">${l.source}</p><a href="${l.url}" target="_blank" rel="noopener" class="text-link">View the original source ↗</a></div>`:''}<p class="micro">${l.quote?'Introduction written for this project':'Original guide: recording and sharing cultural memories'}</p>${l.paragraphs.map(p=>`<p>${p}</p>`).join('')}${id==='symbols'?`<div class="trigram-grid">${Object.values(Culture.trigrams).map(t=>`<div><span>${t.symbol}</span><b>${t.name}</b><small>${t.nature}</small></div>`).join('')}</div>`:''}<div class="purpose"><h2>A question to share</h2><p>${l.question}</p><button class="secondary" data-discuss="${l.id}">Discuss this question →</button></div><div class="actions"><button class="primary" data-read="${id}">${store.read.includes(id)?'✓ Reading complete':'Mark as read'}</button><button class="secondary" data-bookmark="${id}" aria-pressed="${store.bookmarks.includes(id)}">${store.bookmarks.includes(id)?'★ Saved':'☆ Save this guide'}</button></div><a class="text-button" href="#quiz">Try the knowledge quiz →</a></article>`;}
function quiz(){const q=QUIZ[quizIndex],selected=store.answers[quizIndex],answered=Number.isInteger(selected),count=Object.keys(store.answers).filter(k=>Number.isInteger(store.answers[k])).length,correct=QUIZ.filter((q,i)=>store.answers[i]===q.answer).length;return `<div class="screen"><a class="back" href="#library">← Back to Library</a><p class="eyebrow">Knowledge quiz · ${quizIndex+1} / ${QUIZ.length}</p><h1>Learn a little.<br>Understand more.</h1><h2>${q.question}</h2>${q.options.map((o,i)=>`<button class="choice ${answered&&i===q.answer?'correct':''}" data-answer="${i}" ${answered?'disabled':''}>${String.fromCharCode(65+i)} · ${o}${answered&&selected===i?' (your answer)':''}${answered&&i===q.answer?' ✓':''}</button>`).join('')}${answered?`<div class="lens" role="status"><b>${selected===q.answer?'Correct':'Let’s take another look'}</b><p>${q.explanation}</p><a class="text-link" href="#lesson/${q.lesson}">Read the related guide →</a></div>`:''}<div class="actions"><button class="secondary" data-action="quiz-prev" ${quizIndex===0?'disabled':''}>Previous</button><button class="primary" data-action="quiz-next" ${quizIndex===QUIZ.length-1?'disabled':''}>Next</button></div><p class="micro">Answered ${count} / ${QUIZ.length} · Correct: ${correct}</p>${count===QUIZ.length?'<button class="text-button" data-action="quiz-reset">Try again</button>':''}</div>`;}
function community(){const own=store.posts.filter(p=>filter==='全部'||p.tag===filter),topics=TOPICS.filter(p=>filter==='全部'||p.tag===filter);return `<div class="screen"><p class="eyebrow">Discuss · Keep culture in conversation</p><h1>Your memories.<br>Our living heritage.</h1><p>Share a local custom, reflect on a text, or start with a question.</p><div class="notice">Local demo: starter topics are provided by this site. Posts and replies are saved on this device only and are not sent to other people. Live community conversations require a connected service.</div><a class="primary wide" href="#compose" style="margin-top:20px">Share a cultural memory ＋</a><div class="filters" aria-label="Filter topics">${['全部','家乡记忆','经典共读','知识问答'].map(t=>`<button data-filter="${t}" aria-pressed="${filter===t}" class="${filter===t?'selected':''}">${categoryLabel(t)}</button>`).join('')}</div>${own.map(p=>postCard(p,false)).join('')}${topics.map(p=>postCard(p,true)).join('')}${!own.length?'<p class="micro">You have not posted in this category yet. Try one of the starter topics above.</p>':''}</div>`;}
function postCard(p,topic){return `<a class="post-card" href="#thread/${p.id}"><span class="badge">${categoryLabel(p.tag)}</span><span class="micro"> ${topic?'Starter topic':'My post · On this device'}</span><h2>${esc(p.title)}</h2><p>${esc(p.body.slice(0,105))}${p.body.length>105?'…':''}</p><span class="micro">${(store.replies[p.id]||[]).length} local replies · Open discussion →</span></a>`;}
function compose(){return `<div class="screen"><a class="back" href="#community">← Back to Discuss</a><p class="eyebrow">My cultural story</p><h1>Start with a memory.<br>Open a conversation.</h1><p class="micro">Distinguish personal experience from sources. Ask permission before sharing someone else’s story.</p><form id="post-form"><label for="post-tag">Topic</label><select id="post-tag">${['家乡记忆','经典共读','知识问答'].map(t=>`<option value="${t}" ${store.draft.tag===t?'selected':''}>${categoryLabel(t)}</option>`).join('')}</select><label for="post-title">Title (up to 60 characters)</label><input id="post-title" required maxlength="60" value="${esc(store.draft.title)}" placeholder="For example: Our Mid-Autumn traditions"><label for="post-body">Story (up to 1,000 characters)</label><textarea id="post-body" required maxlength="1000" rows="7" placeholder="Where did it happen? Who shared it with you? What would you like to ask?">${esc(store.draft.body)}</textarea><p class="micro">Drafts are saved on this device. Your saved post appears in Discuss, where you can add local replies.</p><button class="primary wide" type="submit">Save post · This device only</button></form></div>`;}
function thread(id){const p=TOPICS.find(x=>x.id===id)||store.posts.find(x=>x.id===id);if(!p)return missing();const topic=TOPICS.some(x=>x.id===id);return `<div class="screen"><a class="back" href="#community">← Back to Discuss</a><p class="eyebrow">${categoryLabel(p.tag)} · ${topic?'Starter topic':'My post · On this device'}</p><h1>${esc(p.title)}</h1><p class="user-text">${esc(p.body)}</p><button class="secondary" data-like="${id}" aria-pressed="${store.liked.includes(id)}">${store.liked.includes(id)?'♥ Topic saved':'♡ Save topic'}</button><div class="section-head"><h2>Local replies · ${(store.replies[id]||[]).length}</h2></div>${(store.replies[id]||[]).map(r=>`<article class="reply"><b>Me · On this device</b><p class="user-text">${esc(r.body)}</p><small>${new Date(r.date).toLocaleDateString('en-GB')}</small></article>`).join('')||'<p class="muted">No local replies yet. Add your first thought.</p>'}<form id="reply-form" data-thread="${id}"><label for="reply-body">Add a memory or ask a question</label><textarea id="reply-body" required maxlength="1000" placeholder="Respect different experiences and include your sources."></textarea><p class="micro">Saved on this device only. Other people will not receive this reply.</p><button class="primary wide" type="submit">Save reply · This device only</button></form></div>`;}
function journal(){return `<div class="screen"><p class="eyebrow">Journal · On this device</p><h1>What you learned.<br>What stayed with you.</h1><div class="stats"><span>Read <strong>${store.read.length}</strong> items</span><span>Save <strong>${store.bookmarks.length}</strong> items</span><span>Coin sessions <strong>${store.records.length}</strong>  sessions</span></div><button class="secondary" data-action="export">Export my Journal ↓</button><div class="section-head"><h2>Saved guides</h2></div>${LESSONS.filter(l=>store.bookmarks.includes(l.id)).map(l=>`<a class="post-card" href="#lesson/${l.id}"><h2>${l.title} →</h2></a>`).join('')||'<p class="muted">No saved guides yet. Visit Library to find your first read.</p>'}<div class="section-head"><h2>Saved discussions</h2></div>${[...TOPICS,...store.posts].filter(p=>store.liked.includes(p.id)).map(p=>`<a class="post-card" href="#thread/${p.id}"><h2>${esc(p.title)} →</h2></a>`).join('')||'<p class="micro">Save a topic in Discuss to find it here again.</p>'}<div class="section-head"><h2>Coin session history</h2></div>${[...store.records].reverse().map(s=>{const r=Culture.decode(s.lines,HEXAGRAMS);return `<article class="record"><span class="micro">${new Date(s.date).toLocaleDateString('en-GB')}</span><h2>${r.hex.symbol} ${r.hex.name}</h2><p class="user-text">${esc(s.note)||'No note for this session.'}</p><a href="#record/${s.id}" class="text-link">Review the six lines →</a></article>`;}).join('')||'<p class="muted">Complete and save a coin session to see your notes here.</p>'}<div class="purpose"><a href="#community">View my posts →</a><p class="micro">${store.posts.length} local posts. Your data does not sync between devices. Export a copy before clearing site data.</p></div></div>`;}
function record(id){const s=store.records.find(x=>x.id===id);if(!s)return missing();const r=Culture.decode(s.lines,HEXAGRAMS);return `<div class="screen"><a class="back" href="#journal">← Back to Journal</a><p class="eyebrow">Review your coin session</p><h1>${r.hex.name}</h1>${yao(s.lines)}<p>Upper trigram: ${r.upper.name} · ${r.upper.nature} / Lower trigram: ${r.lower.name} · ${r.lower.nature}</p><div class="lens"><span class="badge">Reading theme · Editorial guide</span><p>${esc(r.hex.judgment)}</p></div><h2>Your reflection</h2><p class="user-text">${esc(s.note)||'No note saved.'}</p><a class="secondary" href="#lesson/symbols">Keep learning →</a>${Journey.followup()}</div>`;}
function settings(){return `<div class="screen"><a class="back" href="#home">← Back to Home</a><p class="eyebrow">Preferences</p><h1>Settings</h1><section class="purpose"><h2>Language</h2><p>English is the default on first launch. Your preference is saved on this device.</p><div class="language-options" role="group" aria-label="Language"><button class="choice" data-language="en" lang="en" aria-pressed="${window.APP_LANGUAGE==='en'}">English <span>${window.APP_LANGUAGE==='en'?'✓':''}</span></button><button class="choice" data-language="zh-CN" lang="zh-CN" aria-pressed="${window.APP_LANGUAGE==='zh-CN'}">简体中文 <span>${window.APP_LANGUAGE==='zh-CN'?'✓':''}</span></button></div><p class="micro">Changing language keeps your notes, posts and learning history intact.</p></section><a class="secondary" href="#journal">View my Journal →</a></div>`;}
