function render(){window.MotionUI?.before();const [page,id]=route();const views={splash:Studio.splash,home:Studio.welcome,learn:Journey.intro,map:Studio.map,chat:Studio.chat,place:()=>Studio.place(id),explore:home,settings,play:Studio.play,library:Studio.library,lesson:()=>lesson(id),quiz,community,compose,thread:()=>thread(id),journal,record:()=>record(id)};$('#app').innerHTML=(!storageOK?'<p class="notice">Browser storage is unavailable. Your work is held in memory only. Please export a copy.</p>':'')+(views[page]||Studio.welcome)();const nav=['lesson','quiz'].includes(page)?'library':['compose','thread'].includes(page)?'community':page==='record'?'journal':page==='play'?'home':page;document.querySelectorAll('nav a').forEach(a=>{const on=a.dataset.tab===nav;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});Studio.mount(views[page]?page:'home');window.MotionUI?.after(page);}
async function toss(quick){if(busy||!store.current||store.current.lines.length>=6)return;busy=true;const s=store.current;$('.coin-stage')?.classList.add('tossing');document.querySelectorAll('[data-action="toss"],[data-action="quick"]').forEach(b=>b.disabled=true);chime();await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?10:650));s.lines.push(Culture.toss());if(quick)while(s.lines.length<6)s.lines.push(Culture.toss());busy=false;save();if(route()[0]==='play'){render();if(s.lines.length===6)focusHeading();}}
$('#app').addEventListener('input',e=>{const {id,value}=e.target;if(id==='note'&&store.current)store.current.note=value;if(id==='post-title')store.draft.title=value;if(id==='post-body')store.draft.body=value;if(id==='post-tag')store.draft.tag=value;if(['note','post-title','post-body','post-tag'].includes(id))save();});
$('#app').addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='post-form'){const title=$('#post-title').value.trim(),body=$('#post-body').value.trim(),tag=$('#post-tag').value,error=Culture.validatePost(title,body);if(error){toast(error);return;}const id='post-'+Culture.fresh().id;store.posts.push({id,title,body,tag,date:new Date().toISOString()});store.draft={title:'',body:'',tag:'家乡记忆'};const ok=save();go('thread/'+id);toast(ok?'Post saved on this device.':'Held in memory only. Please export a backup.');}else if(e.target.id==='reply-form'){const body=$('#reply-body').value.trim(),id=e.target.dataset.thread;if(!body||body.length>1000){toast('Please enter a reply of 1–1,000 characters.');return;}store.replies[id]??=[];store.replies[id].push({body,date:new Date().toISOString()});const ok=save();render();toast(ok?'Reply saved on this device.':'Held in memory only. Please export a backup.');}});
$('#app').addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
if(b.dataset.language){window.setLanguage(b.dataset.language);return;}
if(b.dataset.bookmark){const id=b.dataset.bookmark;store.bookmarks=store.bookmarks.includes(id)?store.bookmarks.filter(x=>x!==id):[...store.bookmarks,id];redraw();return;}
if(b.dataset.read){if(!store.read.includes(b.dataset.read))store.read.push(b.dataset.read);redraw();toast('Added to your reading history.');return;}
if(b.dataset.discuss){const l=LESSONS.find(l=>l.id===b.dataset.discuss);if(!store.draft.title&&!store.draft.body)store.draft={title:l.question.slice(0,60),body:`My thoughts on ${l.title}: \n`,tag:l.id==='sharing'?'家乡记忆':'经典共读'};save();go('compose');return;}
if(b.dataset.filter){filter=b.dataset.filter;render();return;}
if(b.dataset.like){const id=b.dataset.like;store.liked=store.liked.includes(id)?store.liked.filter(x=>x!==id):[...store.liked,id];redraw();return;}
if(b.dataset.answer!==undefined){if(!Number.isInteger(store.answers[quizIndex]))store.answers[quizIndex]=Number(b.dataset.answer);redraw();return;}
switch(b.dataset.action){case'start':go(store.current?'play':'learn');break;case'toss':toss(false);break;case'quick':toss(true);break;case'save-result':if(store.current?.lines.length===6){store.records.push({...store.current,date:new Date().toISOString()});store.current=null;const ok=save();go('journal');toast(ok?'Saved to Journal.':'Held in memory only. Please export a backup.');}break;case'quiz-prev':quizIndex=Math.max(0,quizIndex-1);render();focusHeading();break;case'quiz-next':quizIndex=Math.min(QUIZ.length-1,quizIndex+1);render();focusHeading();break;case'quiz-reset':store.answers={};quizIndex=0;redraw();focusHeading();break;case'export':{const blob=new Blob([JSON.stringify({...store,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='qianli-coins-journal.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}
});
window.addEventListener('hashchange',()=>{render();focusHeading();});render();
